function parseDetail(html, context) {
  var ctx = context || {};
  var params = ctx.params || {};
  var baseUrl = (ctx.baseUrl || 'https://komiic.cc').replace(/\/$/, '');
  var comicId = ctx.id || params.id;
  if (!comicId) throw new Error('parseDetail: missing comic id');
  var queryStr = 'query detailCombo($comicId: ID!) { recommendComicById(comicId: $comicId) { id } chaptersByComicId(comicId: $comicId) { id serial type dateCreated dateUpdated size __typename } comicByIds(comicIds: [$comicId]) { id title status year imageUrl comicBrief authors { id name __typename } categories { id name __typename } dateUpdated monthViews views favoriteCount lastBookUpdate lastChapterUpdate __typename } }';
  var varsObj = { comicId: comicId };
  return {
    __meta: true,
    __fetchUrl: baseUrl + '/api/query',
    __fetchMethod: 'POST',
    __fetchHeaders: { 'Content-Type': 'application/json', 'Referer': baseUrl + '/' },
    __fetchBody: JSON.stringify({ operationName: 'detailCombo', query: queryStr, variables: varsObj }),
    __processor: '__processDetail',
    __comicId: comicId
  };
}
function getTimeDifference(date) {
  var now = new Date();
  var diff = now - date;
  var msHour = 1000 * 60 * 60;
  var msDay = msHour * 24;
  if (diff < msHour) return '剛剛更新';
  if (diff < msDay) return Math.floor(diff / msHour) + '小時前更新';
  return Math.floor(diff / msDay) + '天前更新';
}
function __processDetail(graphqlJson, context) {
  var ctx = context || {};
  var params = ctx.params || {};
  var baseUrl = (ctx.baseUrl || 'https://komiic.cc').replace(/\/$/, '');
  var comicId = ctx.__comicId || ctx.id || params.id;
  if (!graphqlJson || !graphqlJson.data) throw new Error('parseDetail: empty response');
  var d = graphqlJson.data;
  var recIds = (d.recommendComicById || []).map(function(x) { return String(x && typeof x === 'object' ? x.id : x); });
  var allIds = recIds.slice();
  allIds.push(comicId);
  var comics = d.comicByIds || [];
  var chapters = d.chaptersByComicId || [];
  var info = null;
  var idStr = String(comicId);
  var recComics = [];
  for (var i = 0; i < comics.length; i++) {
    var c = comics[i];
    if (String(c.id) === idStr) {
      info = c;
    } else if (recIds.indexOf(String(c.id)) !== -1) {
      recComics.push(c);
    }
  }
  if (!info && comics.length > 0) info = comics[0];
  if (!info) throw new Error('parseDetail: comic not found');
  var chapterMap = {};
  chapters.forEach(function(c) {
    chapterMap[c.id] = c.type === 'book' ? '卷' + c.serial : String(c.serial);
  });
  var author = '';
  if (info.authors && info.authors.length > 0) author = info.authors[0].name;
  var authorSlug = author;
  var genre = '';
  if (info.categories && info.categories.length > 0) genre = info.categories[0].name;
  var tags = [];
  if (info.categories) info.categories.forEach(function(c) { if (c.name && tags.indexOf(c.name) === -1) tags.push(c.name); });
  var updatedAt = '';
  if (info.dateUpdated) {
    var ud = info.dateUpdated;
    if (typeof ud === 'number') {
      var ts = ud;
      if (ts < 1000000000000) ts = ts * 1000;
      updatedAt = new Date(ts).toISOString();
    } else {
      updatedAt = String(ud);
    }
  }
  var description = '';
  if (info.comicBrief) description = String(info.comicBrief).trim();
  if (!description && info.dateUpdated) {
    try { description = getTimeDifference(new Date(updatedAt || info.dateUpdated)); } catch (e) {}
  }
  var recommendations = recComics.map(function(rc) {
    return {
      title: rc.title,
      coverUrl: coverProxy(rc.imageUrl),
      comicId: rc.id,
      url: baseUrl + '/comic/' + rc.id
    };
  });
  return {
    title: info.title,
    coverUrl: coverProxy(info.imageUrl),
    status: info.status,
    author: author,
    authorSlug: authorSlug,
    genre: genre,
    tags: tags,
    description: description,
    updatedAt: updatedAt,
    chapters: chapterMap,
    recommendations: recommendations
  };
}

